// Initial file generated by Claude Sonnet 5.5

import { describe, expect, it, vi } from "vitest";

import { buildNetsBloxURL, NETSBLOX_ORIGIN, parseStarterURL } from "@/core/netsbloxURL.ts";

const DEFAULT = `${NETSBLOX_ORIGIN}/`;

describe("parseStarterURL", () => {

  it("uses the default when nothing is supplied", () => {
    expect(parseStarterURL(null).href).toBe(DEFAULT);
  });

  it("accepts URLs on the NetsBlox editor origin, keeping path and query", () => {
    const url = parseStarterURL("https://editor.netsblox.org/?run=true&extensions=%5B%5D");
    expect(url.origin).toBe(NETSBLOX_ORIGIN);
    expect(url.searchParams.get("run")).toBe("true");
  });

  it.each([
    "javascript:alert(document.domain)//"
  , "JaVaScRiPt:alert(1)"
  , " javascript:alert(1)"
  , "data:text/html,<script>alert(1)</script>"
  , "http://editor.netsblox.org/"
  , "https://evil.example/"
  , "https://editor.netsblox.org.evil.example/"
  , "https://editor.netsblox.org@evil.example/"
  , "https://evil.example/https://editor.netsblox.org/"
  , "https://editor.netsblox.org:8443/"
  , "https://user:pw@editor.netsblox.org/"
  , "//evil.example/"
  , "/relative/path"
  , ""
  , "not a url"
  ])("falls back to the default for %j", (bad) => {
    vi.spyOn(console, "warn").mockImplementation(() => {});
    const url = parseStarterURL(bad);
    expect(url.href).toBe(DEFAULT);
  });

});

describe("buildNetsBloxURL", () => {

  const params = { Username: "Ana B", ProjectName: "", editMode: "true", hash: "abc", gallery: "https://zocalo.example" };

  it("adds the synthesized parameters to the (validated) starter URL", () => {
    const url = new URL(buildNetsBloxURL("https://editor.netsblox.org/?run=true", params));
    expect(url.origin).toBe(NETSBLOX_ORIGIN);
    expect(url.searchParams.get("run")).toBe("true");
    expect(url.searchParams.get("Username")).toBe("Ana B");
    expect(url.searchParams.get("gallery")).toBe("https://zocalo.example");
  });

  it("overrides a Username supplied inside the starter URL rather than duplicating it", () => {
    const url = new URL(buildNetsBloxURL("https://editor.netsblox.org/?Username=Mallory", params));
    expect(url.searchParams.getAll("Username")).toEqual(["Ana B"]);
  });

  it("never produces a non-https result, whatever the input", () => {
    vi.spyOn(console, "warn").mockImplementation(() => {});
    const out = buildNetsBloxURL("javascript:alert(1)//", params);
    expect(out.startsWith(`${NETSBLOX_ORIGIN}/`)).toBe(true);
  });

});
